import{_ as a,o as e,c as r,O as d}from"./chunks/framework.db831a78.js";const u=JSON.parse('{"title":"算法与数据结构","description":"","frontmatter":{},"headers":[],"relativePath":"algorithm/index.md","filePath":"algorithm/index.md","lastUpdated":1788941422000}'),o={name:"algorithm/index.md"};function l(h,t,i,n,s,f){return e(),r("div",null,t[0]||(t[0]=[d('<h1 id="算法与数据结构" tabindex="-1">算法与数据结构 <a class="header-anchor" href="#算法与数据结构" aria-label="Permalink to &quot;算法与数据结构&quot;">​</a></h1><blockquote><p>通用算法与数据结构知识库（刷题向），面向求职面试与算法入门，正文统一用 Python 伪代码示意，复杂度一律用表格给出。</p></blockquote><hr><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li>本系列讲的是<strong>脱离具体语言、可迁移到任何面试场景</strong>的通用算法知识：复杂度分析、数据结构选型、树与图、排序与查找、动态规划与回溯、高频套路。</li><li>定位是「面试 + 刷题」：每篇正文按「<strong>识别特征 → 思路 → 模板伪代码 → 复杂度表 → 代表题</strong>」组织，可直接对着力扣（LeetCode）、牛客刷题使用。</li><li>分工说明：本系列只讲算法本身，不绑定语言框架；Java 集合类、并发、JVM 等见<a href="./../interview/后端/Java/">后端 Java 面试目录</a>。</li></ul><hr><h2 id="使用建议-刷题向" tabindex="-1">使用建议（刷题向） <a class="header-anchor" href="#使用建议-刷题向" aria-label="Permalink to &quot;使用建议（刷题向）&quot;">​</a></h2><ol><li>先读 <a href="./复杂度分析">复杂度分析</a>：没有复杂度概念，无法判断一个解法「能不能过数据规模」。</li><li>再读 <a href="./常用数据结构">常用数据结构</a>：熟练数组/链表/栈/队列/哈希表/堆的原理、API 与复杂度。</li><li>分专题推进：<a href="./树与图">树与图</a> → <a href="./排序与查找">排序与查找</a> → <a href="./动态规划与回溯">动态规划与回溯</a> → <a href="./高频算法题套路">高频算法题套路</a>。</li><li>刷题时：先看 <a href="./高频算法题套路">高频算法题套路</a> 的「识别特征」命中题型，再套模板，最后去力扣/牛客验证。</li><li>复盘时：把每道错题归类到对应套路下，逐步形成自己的「题感清单」。</li></ol><hr><h2 id="目录覆盖表" tabindex="-1">目录覆盖表 <a class="header-anchor" href="#目录覆盖表" aria-label="Permalink to &quot;目录覆盖表&quot;">​</a></h2><table><thead><tr><th>文件</th><th>覆盖内容</th><th>优先级</th></tr></thead><tbody><tr><td><a href="./复杂度分析">复杂度分析</a></td><td>大 O、时间/空间复杂度、主定理简介、最好/最坏/平均/均摊、易错点</td><td>★★★ 最先读</td></tr><tr><td><a href="./常用数据结构">常用数据结构</a></td><td>数组/链表/栈/队列/哈希表/堆：原理、复杂度表、API、典型坑</td><td>★★★</td></tr><tr><td><a href="./树与图">树与图</a></td><td>二叉树四种遍历、BST、平衡树、堆；图遍历、拓扑排序、Dijkstra、并查集</td><td>★★★</td></tr><tr><td><a href="./排序与查找">排序与查找</a></td><td>八大排序思路与对比总表、TopK、二分查找变体、外排序</td><td>★★★</td></tr><tr><td><a href="./动态规划与回溯">动态规划与回溯</a></td><td>DP 五步法、四大经典题拆解、记忆化搜索、回溯框架与剪枝</td><td>★★☆</td></tr><tr><td><a href="./高频算法题套路">高频算法题套路</a></td><td>双指针、滑动窗口、前缀和/差分、单调栈、BFS/DFS 模板、位运算、TopK</td><td>★★★ 常翻</td></tr></tbody></table><hr><h2 id="刷题路线一句话" tabindex="-1">刷题路线一句话 <a class="header-anchor" href="#刷题路线一句话" aria-label="Permalink to &quot;刷题路线一句话&quot;">​</a></h2><blockquote><p>先会「遍历与暴力」（数组、链表、树、BFS/DFS），再会「有序加速」（二分、排序、堆），最后攻克「状态与决策」（DP、回溯）——分组路线详见<a href="./高频算法题套路">高频算法题套路</a> 最后一节。</p></blockquote>',14)]))}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
